CREATE OR REPLACE FUNCTION public.notify_on_activity_reaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_author uuid;
  v_href text;
begin
  select p.author_id, public.post_href(p.id)
  into v_author, v_href
  from public.activity_posts p
  where p.id = new.post_id;

  perform public.notify(
    v_author, 'reaction', 'engagement',
    public.actor_name(new.user_id) || ' reacted ' || new.emoji,
    null, v_href, new.user_id
  );
  return new;
end;
$function$;

grant execute on function public.notify_on_activity_reaction() to anon;
grant execute on function public.notify_on_activity_reaction() to authenticated;
grant execute on function public.notify_on_activity_reaction() to public;
grant execute on function public.notify_on_activity_reaction() to service_role;
